+	} else {
+		fmt.Fprintf(&b, "showing first ~%d tokens; ", ApproximateTokens(head))
+	}
+	fmt.Fprintf(&b, "omitted ~%d tokens.%s]", ApproximateTokens(omitted), truncHint(hint))
+	if headTail {
+		b.WriteString("\n\n")
 	}
