+	if m.entries[1].status != "running" || m.entries[1].label != "Bash(\"date\")" {
+		t.Fatalf("second entry should be active tool: %#v", m.entries[1])
+	}
+	if line := stripANSI(toolStatusLine(m.entries[1])); line != `Bash("date")` {
