+				`{"model":"qwen2.5-coder:32b","description":"old coding model"},`+
+				`{"model":"qwen3.5","description":"new local model"}`+
+				`]}`)
+		case "/api/tags":
+			fmt.Fprint(w, `{"models":[`+
+				`{"name":"qwen2.5:14b"},`+
+				`{"name":"llama3.2:latest"},`+
