-type errOnBangReader struct {
-	s string
-	n int
-}
-
-func (e *errOnBangReader) Read(p []byte) (int, error) {
-	if len(p) < 1 {
-		return 0, io.ErrShortBuffer
-	}
-	if e.n >= len(p) {
-		return 0, io.EOF
-	}
-	if e.s[e.n] == '!' {
-		return 0, errors.New("bang")
-	}
-	p[0] = e.s[e.n]
-	e.n++
-	return 1, nil
-}
