diff --git a/packages/reactivity/__tests__/effectScope.spec.ts b/packages/reactivity/__tests__/effectScope.spec.ts
index 071c8286c4f..0bb752659d8 100644
--- a/packages/reactivity/__tests__/effectScope.spec.ts
